class PgIdentityRepository:
    def __init__(self, conn: AsyncConnection) -> None:
        self._conn = conn

    async def link(self, issuer: str, subject: str, claims: dict[str, Any]) -> int:
        cur = await self._conn.execute(
            "SELECT user_id FROM oidc_identities WHERE issuer = %s AND subject = %s",
            (issuer, subject),
        )
        if (row := await cur.fetchone()) is not None:
            return row[0]

        if claims.get("email_verified") is not True or not claims.get("email"):
            raise ForbiddenError("Your university account has no verified email.")
        cur = await self._conn.execute(
            "SELECT id FROM users WHERE lower(email) = lower(%s) AND role IN ('staff', 'admin')",
            (claims["email"],),
        )
        if (row := await cur.fetchone()) is None:
            raise ForbiddenError("Ask an admin to add you as staff first.")
        await self._conn.execute(
            "INSERT INTO oidc_identities (issuer, subject, user_id) VALUES (%s, %s, %s)",
            (issuer, subject, row[0]),
        )
        return row[0]

async def get_principal(
    conn: Conn,
    tokens: Annotated[AccessTokens, Depends(get_tokens)],
    session: Annotated[str | None, Cookie(alias=SESSION_COOKIE)] = None,
    credentials: Annotated[HTTPAuthorizationCredentials | None, Depends(bearer)] = None,
    api_key: Annotated[str | None, Depends(api_key_header)] = None,
) -> Principal | None:
    if session is not None:
        user = await PgUserRepository(conn).get_by_session(session)
        if user is None:
            raise UnauthorizedError("Your session has ended. Sign in again.")
        return user_principal("session", user.id, user.role, user.building_id)
    if credentials is not None:
        try:
            claims = tokens.verify(credentials.credentials)
        except Exception:
            raise UnauthorizedError("The access token is invalid or expired.") from None
        return user_principal(
            "bearer", int(claims["sub"]), claims["role"], claims["building_id"], claims["scope"].split()
        )
    if api_key is not None:
        key = await PgApiKeyRepository(conn).check(api_key)
        if key is None:
            raise UnauthorizedError("The API key is invalid or revoked.")
        return Principal("api-key", None, None, key["building_id"], frozenset(key["scopes"]))
    return None


async def require_principal(
    security_scopes: SecurityScopes,
    principal: Annotated[Principal | None, Depends(get_principal)],
) -> Principal:
    if principal is None:
        raise UnauthorizedError()
    missing = [s for s in security_scopes.scopes if s not in principal.scopes]
    if missing:
        raise ForbiddenError(f"This needs the {' '.join(missing)} scope.")
    return principal

